-- ===================== GDOCS =====================
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_1e468a9d69ea0f0a2001f5', 'LLC ground rules (Combo Fighter and whatever else we take)', 'leonard.hayes@harmonygames.co', '["robert@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'LLC ground rules (Combo Fighter and whatever else we take)\nThis is the lifestyle route I posted about in #executives. The LLC is the new one Blake and I are setting up for the three of us, and anything Harmony Games owns (the games with their art and listings, and the equipment) comes to it only through Sunset''s sale, the way I wrote after the call on Wednesday. Services we keep running just move their billing to the LLC.\nThe plan runs March 1 to May 31.\nDomino Delights and Zombie Match come over only if what each made in January, going by the warehouse''s daily revenue table, covers what its own hosting bills now, whatever we said about them before. Combo Fighter comes over either way, it''s the reason we''re doing this. A game that comes over brings what it needs to keep running, its accounts and its player support.\nCost every item at what it bills now, going by whoever runs it, not by what HG used to pay.\nWhat we already decided to keep or cancel for the shutdown in #winddown stays decided.\nPay for anyone who stays on is a separate conversation once we know the running cost; this plan is only what bills us every month, no one-offs or yearly fees.\nHow things move is on the LLC card on our board.\n', '[{"start": 0, "end": 59, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 59, "end": 1214, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '89aa42aa1b', 'f_1e468a9d69ea0f0a2001f5', '2026-02-12T23:46:00Z', '2026-02-12T23:46:00Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_a7af6f358dd5648c11a608', 'LLC notes (Monday)', 'leonard.hayes@harmonygames.co', '["robert@harmonygames.co", "arthur.blake@harmonygames.co"]', 'private', E'LLC notes (Monday)\nIf we go the lifestyle route: Calm Play could hold it. DD and ZM both come with CF. Servers about $1k a month, Blake is looking at it.\n', '[{"start": 0, "end": 19, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 19, "end": 154, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '8e88812389', 'f_a7af6f358dd5648c11a608', '2026-02-09T23:55:00Z', '2026-02-09T23:55:00Z');
