INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('6908b2f17c379e809aafa6b2b169f4bf', '1770938400.370665', 'C09UHHN6PFZ', 'message', 'EMPLOYEE_0038_SLACK_ID', 'of the meta campaigns only the VO one is still on (I paused the install one; the unity playable test just uses up the $100 left on unity). it''s still learning so meta is barely billing it, but it''s set to $100/day capped at $3,000 a month and that''s what it runs at from March. it''s on my card till the end of Feb and moves to the LLC from March if we keep CF going, so count it in what the LLC costs', '73ec270a3d07eb8d8488384898be079e', '1770404397.819789', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2026-02-12T23:20:00Z', '{}');
