VALUES ('ad623a2f0d4387109d108e767b174609', '1770952200.665739', 'D04V95AAAHW', 'message', 'EMPLOYEE_0025_SLACK_ID', 'fyi Domino''s prod account is down to $140 a month now, one small task and the db at its floor. that''s what it bills from March. it''s still on HG''s AWS bill till then', 'bc4bc3d0e2a0ea6ae92cb2a9712e8f76', '1770056235.480619', 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2026-02-13T03:10:00Z', '{}');
