INSERT INTO slack.slack_messages (id, ts, channel_id, type, user_id, text, thread_parent_id, thread_ts_legacy, reply_count, reply_users_count, latest_reply, is_activity_message, subtype, reactions_json, files_json, attachments_json, created_at, metadata_json)
VALUES ('6257a3c4456db0bd2aeb872619d7a364', '1770961200.890407', 'D04UP2L3E3S', 'message', 'EMPLOYEE_0038_SLACK_ID', 'if you really want to keep combo fighter going, let''s set the LLC up properly. I put everything we might need from HG into the LLC project in linear, one issue each. go through them and make the call on each one: what the LLC takes if Sunset can''t sell it, what it costs us March through May, and who pays what. the ground rules doc has how we decide. lay the sheet out like my draft from Tuesday, keep it in your drive and share it with Blake and me. leave your call on each issue too so we can see it there. I''ll email you how we split the money. then tell me here what you''d do and what it costs each of us a month. we decide on Monday''s call', NULL, NULL, 0, 0, NULL, false, NULL, '[]', '[]', '[]', '2026-02-13T05:40:00Z', '{}');
