VALUES ('698e6548aa9516b76c4ab475', 'LLC: what we take from HG', '640643a3fd8f3ca308d9318e', '640643a3fd8f3ca308d93195', 'Robert makes the call on each item in the Linear project. Whoever runs an item today moves it. Anything that comes through Sunset''s sale moves when the sale closes. Anything that already has its own deadline keeps it; everything else moves by March 1.', 3.0, false, NULL, false, '[]', '[]', 456, NULL, NULL, 'https://PERSON_6092_TRELLO_USERNAME.com/c/N6TBAK8A/456-llc-what-we-take-from-hg', '2026-02-12T23:42:00Z', NULL, '{"attachments": 0, "attachmentsByType": {"trello": {"board": 0, "card": 0}}, "checkItems": 0, "checkItemsChecked": 0, "checkItemsEarliestDue": null, "comments": 0, "description": true, "due": null, "dueComplete": false, "externalSource": null, "fogbugz": "", "lastUpdatedByAi": false, "location": false, "maliciousAttachments": 0, "start": null, "votes": 0}');
