VALUES ('robert@harmonygames.co/<136285951.151027292.1770967800000@email.apple.com>', 'robert@harmonygames.co/1856994331853686118', 'robert@harmonygames.co', '["INBOX", "CATEGORY_UPDATES", "Label_ad4e31dc09", "Label_aeb79a643f"]', 'Hello [PERSON_NAME_0054], Thank you for submitting your items for review. We appreciate your enthusiasm for Apple platforms. As you know, we', 1770967800000, '2026-02-13T07:30:00Z', 1924, 'We noticed an issue with your submission.', 'SVC_4131_EMAIL', 'SVC_4131_NAME', '["robert <robert@harmonygames.co>"]', '[]', '[]', '[]', E'Hello [PERSON_NAME_0054],\r\n\r\nThank you for submitting your items for review. We appreciate your enthusiasm for Apple platforms. As you know, we want to provide a safe experience for users to get apps and a great opportunity for all developers to be successful. We do this by offering a highly curated App Store where every submission is reviewed by experts and an editorial team helps users discover new apps every day.\r\n\r\nDuring our review, we noticed an issue with your submission.\r\n\r\nApp Name: Domino Delights\r\nSubmission ID: [IDENTIFIER_101611]\r\n\r\nWe look forward to working with you to resolve the issues with the following items:\r\n\r\nGuideline 1.5 - Safety - Developer Information\r\nThe support option in the app only opens an email draft, and on a device without a mail account set up it does nothing, so users can''t reach you from the app. Please add a support URL or another way to contact you in the app.\r\n\r\nYou can also view this information on the App Review page in App Store Connect.\r\n\r\nBest regards,\r\nApp Review', NULL, '[{"name": "Message-ID", "value": "<136285951.151027292.1770967800000@email.apple.com>"}, {"name": "Date", "value": "Fri, 13 Feb 2026 07:30:00 +0000"}, {"name": "Subject", "value": "We noticed an issue with your submission."}, {"name": "From", "value": "SVC_4131_NAME <SVC_4131_EMAIL>"}, {"name": "To", "value": "robert@harmonygames.co"}]', NULL, NULL, NULL, '[]');
